/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AperiodicOrderScreen } from "../../src/aperiodic-order/AperiodicOrderScreen.js";
import CrystalLatticeColors from "../../src/CrystalLatticeColors.js";
import { ClosePackingScreen } from "../../src/close-packing/ClosePackingScreen.js";
import { CubicSystemsScreen } from "../../src/cubic-systems/CubicSystemsScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { Lattices2DScreen } from "../../src/lattices-2d/Lattices2DScreen.js";
import { MillerIndicesScreen } from "../../src/miller-indices/MillerIndicesScreen.js";
import { CrystalLatticePreferencesModel } from "../../src/preferences/CrystalLatticePreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from crystalLatticeQueryParameters.
  const simPreferences = new CrystalLatticePreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new Lattices2DScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().lattices2DStringProperty,
      tandem: Tandem.ROOT.createTandem("lattices2DScreen"),
      backgroundColorProperty: CrystalLatticeColors.backgroundColorProperty,
      preferences: simPreferences,
    }),
    new CubicSystemsScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().cubicSystemsStringProperty,
      tandem: Tandem.ROOT.createTandem("cubicSystemsScreen"),
      backgroundColorProperty: CrystalLatticeColors.backgroundColorProperty,
    }),
    new ClosePackingScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().closePackingStringProperty,
      tandem: Tandem.ROOT.createTandem("closePackingScreen"),
      backgroundColorProperty: CrystalLatticeColors.backgroundColorProperty,
    }),
    new MillerIndicesScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().millerIndicesStringProperty,
      tandem: Tandem.ROOT.createTandem("millerIndicesScreen"),
      backgroundColorProperty: CrystalLatticeColors.backgroundColorProperty,
      preferences: simPreferences,
    }),
    new AperiodicOrderScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().aperiodicOrderStringProperty,
      tandem: Tandem.ROOT.createTandem("aperiodicOrderScreen"),
      backgroundColorProperty: CrystalLatticeColors.backgroundColorProperty,
      preferences: simPreferences,
    }),
  ];

  return { screens, tracked: { CrystalLatticeColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
